[groq-gpt-oss] evals/prompts/lib/skill-p:
Below is a **complete, copy‑and‑paste HTML page** that works with **MapLibre GL JS v6** and shows how to

1. **Load 40 + SVG icons** that live on your own domain.  
2. **Register each SVG at runtime** with `map.addImage`.  
3. **Add a GeoJSON source** that contains ~5 000 venue points, each having a `category` property.  
4. **Draw the venues with a symbol layer** whose `icon-image` is taken from the `category` property.  
5. **Let MapLibre’s built‑in collision handling** keep the icons from piling up when you are zoomed out (the default behaviour – `icon-allow-overlap: false`).

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>MapLibre – 5 000 venues with SVG category icons</title>
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <!-- MapLibre GL JS v6 -->
  <link href="https://unpkg.com/maplibre-gl@6.1.0/dist/maplibre-gl.css" rel="stylesheet"/>
  <script src="https://unpkg.com/maplibre-gl@6.1.0/dist/maplibre-gl.js"></script>

  <style>
    body, html { margin:0; padding:0; height:100%; }
    #map { position:absolute; top:0; bottom:0; width:100%; }
  </style>
</head>
<body>

<div id="map"></div>

<script>
/* --------------------------------------------------------------
   1️⃣  CONFIGURATION
   -------------------------------------------------------------- */
const MAP_STYLE = 'https://demotiles.maplibre.org/style.json';   // any style you like
const MAP_CENTER = [ -122.447303, 37.753574 ]; // San Francisco (lon, lat)
const MAP_ZOOM   = 12;

// Where your SVG icons live – one file per category.
// The file name (without extension) must be exactly the same as the
// value that appears in the GeoJSON `category` property.
const ICON_BASE_URL = 'https://example.com/icons/';   // <-- change to your domain
const CATEGORIES = [
  // list every category that appears in your data.
  // The order does not matter – we’ll load them all in parallel.
  'cafe', 'restaurant', 'bar', 'museum', 'park', 'hotel',
  'bank', 'pharmacy', 'school', 'university', 'library',
  // … add the rest up to ~40 …
];

// --------------------------------------------------------------
// 2️⃣  HELPER: load a single SVG and turn it into an Image element
// --------------------------------------------------------------
function loadSvgAsImage(url) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    // Important for cross‑origin SVGs – the image must be CORS‑enabled.
    img.crossOrigin = 'anonymous';
    img.onload = () => resolve(img);
    img.onerror = (e) => reject(new Error(`Failed to load ${url}`));
    img.src = url;
  });
}

// --------------------------------------------------------------
// 3️⃣  MAIN – initialise the map, load icons, add source & layer
// --------------------------------------------------------------
(async () => {
  // ----------------------------------------------------------------
  // 3.1 Initialise the map (style may be any MapLibre style you like)
  // ----------------------------------------------------------------
  const map = new maplibregl.Map({
    container: 'map',
    style: MAP_STYLE,
    center: MAP_CENTER,
    zoom: MAP_ZOOM,
    // optional – improves performance for many points
    // (you can also enable it later with map.setRenderWorldCopies(true))
    preserveDrawingBuffer: false,
  });

  // Wait until the style (and its default sprite) is fully loaded.
  await new Promise(resolve => map.once('style.load', resolve));

  // ----------------------------------------------------------------
  // 3.2 Load every SVG, then register it with map.addImage()
  // ----------------------------------------------------------------
  const loadPromises = CATEGORIES.map(cat => {
    const url = `${ICON_BASE_URL}${cat}.svg`;
    return loadSvgAsImage(url)
      .then(img => {
        // `addImage` rasterises the SVG at the element's intrinsic size.
        // You can pass extra options (pixelRatio, sdf, stretchX, …) if you need them.
        map.addImage(cat, img, { sdf: false, pixelRatio: 1 });
        console.log(`✅ registered icon "${cat}"`);
      })
      .catch(err => console.warn(err.message));
  });

  // Wait for *all* icons to be registered before we add the data layer.
  await Promise.all(loadPromises);
  console.log('All icons loaded (or attempted).');

  // ----------------------------------------------------------------
  // 3.3 Add the GeoJSON source with ~5 000 venues
  // ----------------------------------------------------------------
  // In a real app you would fetch this from a server.  Here we generate
  // a tiny random sample for demonstration – replace with your own data.
  function generateRandomVenues(count) {
    const features = [];
    for (let i = 0; i < count; i++) {
      const lon = MAP_CENTER[0] + (Math.random() - 0.5) * 0.2;
      const lat = MAP_CENTER[1] + (Math.random() - 0.5) * 0.2;
      const cat = CATEGORIES[Math.floor(Math.random() * CATEGORIES.length)];
      features.push({
        type: 'Feature',
        geometry: { type: 'Point', coordinates: [lon, lat] },
        properties: { category: cat, name: `${cat} #${i}` }
      });
    }
    return { type: 'FeatureCollection', features };
  }

  const venuesGeoJSON = generateRandomVenues(5000); // replace with your real data

  map.addSource('venues', {
    type: 'geojson',
    data: venuesGeoJSON,
    // optional: clustering if you want a different visual at very low zooms
    // cluster: true,
    // clusterRadius: 50,
  });

  // ----------------------------------------------------------------
  // 3.4 Add a symbol layer that uses the category as the icon name
  // ----------------------------------------------------------------
  map.addLayer({
    id: 'venue-icons',
    type: 'symbol',
    source: 'venues',
    layout: {
      // The property name must match the id we used in addImage().
      // Using an expression lets us fall back to a generic icon if a
      // category is missing from the sprite.
      'icon-image': ['coalesce', ['get', 'category'], 'default-icon'],

      // Keep the default collision handling (icon-allow-overlap: false)
      // so icons that would overlap are hidden when you are zoomed out.
      // You can tweak the tolerance with `icon-allow-overlap` /
      // `icon-ignore-placement` if you need a different feel.
      // Example:
      // 'icon-allow-overlap': false,
      // 'icon-ignore-placement': false,

      // Optional – make the icons a little larger at higher zooms.
      // This is purely cosmetic; remove if you don’t want it.
      'icon-size': [
        'interpolate',
        ['linear'],
        ['zoom'],
        10, 0.6,
        14, 1.0,
        18, 1.4
      ]
    },
    paint: {
      // If you want a halo around the SVG (useful on busy raster basemaps)
      // 'icon-halo-color': '#fff',
      // 'icon-halo-width': 1,
    }
  });

  // ----------------------------------------------------------------
  // 3️⃣  OPTIONAL: add a label layer (name of the venue) – not required
  // ----------------------------------------------------------------
  map.addLayer({
    id: 'venue-labels',
    type: 'symbol',
    source: 'venues',
    layout: {
      'text-field': ['get', 'name'],
      'text-font': ['Open Sans Regular', 'Arial Unicode MS Regular'],
      'text-size': 12,
      'text-offset': [0, 1.2],
      'text-anchor': 'top',
      // Show labels only when we are reasonably zoomed in
      'text-max-width': 8,
      'text-allow-overlap': false,
      'text-ignore-placement': false
    },
    paint: {
      'text-color': '#222',
      'text-halo-color': '#fff',
      'text-halo-width': 1
    }
  });

  console.log('✅ Map ready – venues with category SVG icons are displayed.');
})();
</script>

</body>
</html>
```

### How the code works

| Step | What happens | Why it matters for your use‑case |
|------|--------------|---------------------------------|
| **1️⃣ Configuration** | Define the style URL, map centre/zoom, the base URL where the SVGs live, and the list of category names. | Keeps the rest of the script generic – you only need to change the three constants. |
| **2️⃣ `loadSvgAsImage`** | Returns a `Promise` that resolves with an `HTMLImageElement` once the SVG has loaded (CORS‑enabled). | `map.addImage` works with any raster image element; an SVG is rasterised at its intrinsic size when added. |
| **3.1 Map init** | Creates the `maplibregl.Map` and waits for the `style.load` event. | Guarantees the style (and its default sprite) is ready before we start registering our own images. |
| **3.2 Register icons** | For every category we fetch the SVG, then call `map.addImage(category, img)`. The **image id** is exactly the category string, so later we can reference it directly in the layer. | No need to rebuild a sprite sheet; the 40 icons are loaded once (≈ 40 × HTTP GET) and cached by the browser. |
| **3.3 GeoJSON source** | Adds a `geojson` source containing ~5 000 point features, each with a `category` property. | The source can be swapped for a real endpoint (`url: '/venues.geojson'`) – the rest of the code stays the same. |
| **3.4 Symbol layer** | Uses an expression `['get', 'category']` for `icon-image`. The default collision handling (`icon-allow-overlap: false`) automatically hides overlapping icons when you are zoomed out. | Exactly what you asked for: “icons shouldn’t pile up on top of each other”. |
| **Optional label layer** | Shows the venue name as a text label, also subject to collision handling. | Demonstrates that you can combine icons and text without extra work. |

### Tweaking collision handling (optional)

- **Show every icon regardless of overlap** – set `'icon-allow-overlap': true` (or `'icon-overlap': 'always'`).  
- **Make icons ignore placement but still be considered for text collision** – `'icon-ignore-placement': true`.  
- **Add a halo** – uncomment the `icon-halo-color` / `icon-halo-width` paint properties.

### Things to remember

* **CORS** – The SVG files must be served with `Access‑Control‑Allow‑Origin: *` (or your site’s origin). Otherwise `loadSvgAsImage` will fail.  
* **Pixel ratio** – If you have `@2x` versions you can register them with `pixelRatio: 2` in the `addImage` options.  
* **Performance** – 5 000 points is well within MapLibre’s comfort zone. If you ever go to > 50 000 you might want to enable clustering or use a WebGL‑based point‑cloud approach.  

That’s it! Drop the HTML into a file, point `ICON_BASE_URL` at the folder that contains your 40 + SVG icons (named exactly like the `category` values), replace the generated GeoJSON with your real venue data, and you’ll have a fully functional map where each venue shows its proper SVG icon and icons automatically hide when they would otherwise overlap. Happy mapping!

Below is a **complete, copy‑and‑paste HTML page** that works with **MapLibre GL JS v6** and shows how to

1. **Load 40 + SVG icons** that live on your own domain.  
2. **Register each SVG at runtime** with `map.addImage`.  
3. **Add a GeoJSON source** that contains ~5 000 venue points, each having a `category` property.  
4. **Draw the venues with a symbol layer** whose `icon-image` is taken from the `category` property.  
5. **Let MapLibre’s built‑in collision handling** keep the icons from piling up when you are zoomed out (the default behaviour – `icon-allow-overlap: false`).

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>MapLibre – 5 000 venues with SVG category icons</title>
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <!-- MapLibre GL JS v6 -->
  <link href="https://unpkg.com/maplibre-gl@6.1.0/dist/maplibre-gl.css" rel="stylesheet"/>
  <script src="https://unpkg.com/maplibre-gl@6.1.0/dist/maplibre-gl.js"></script>

  <style>
    body, html { margin:0; padding:0; height:100%; }
    #map { position:absolute; top:0; bottom:0; width:100%; }
  </style>
</head>
<body>

<div id="map"></div>

<script>
/* --------------------------------------------------------------
   1️⃣  CONFIGURATION
   -------------------------------------------------------------- */
const MAP_STYLE = 'https://demotiles.maplibre.org/style.json';   // any style you like
const MAP_CENTER = [ -122.447303, 37.753574 ]; // San Francisco (lon, lat)
const MAP_ZOOM   = 12;

// Where your SVG icons live – one file per category.
// The file name (without extension) must be exactly the same as the
// value that appears in the GeoJSON `category` property.
const ICON_BASE_URL = 'https://example.com/icons/';   // <-- change to your domain
const CATEGORIES = [
  // list every category that appears in your data.
  // The order does not matter – we’ll load them all in parallel.
  'cafe', 'restaurant', 'bar', 'museum', 'park', 'hotel',
  'bank', 'pharmacy', 'school', 'university', 'hospital',
  // … add the rest up to ~40 …
];

// --------------------------------------------------------------
// 2️⃣  HELPER: load a single SVG and turn it into an Image element
// --------------------------------------------------------------
function loadSvgAsImage(url) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    // Important for cross‑origin SVGs – the image must be CORS‑enabled.
    img.crossOrigin = 'anonymous';
    img.onload = () => resolve(img);
    img.onerror = (e) => reject(new Error(`Failed to load ${url}`));
    img.src = url;
  });
}

// --------------------------------------------------------------
// 3️⃣  MAIN – initialise the map, load icons, add source & layer
// --------------------------------------------------------------
(async () => {
  // ----------------------------------------------------------------
  // 3.1 Initialise the map (style may be any MapLibre style you like)
  // ----------------------------------------------------------------
  const map = new maplibregl.Map({
    container: 'map',
    style: MAP_STYLE,
    center: MAP_CENTER,
    zoom: MAP_ZOOM,
    // optional – improves label readability on high‑dpi screens
    pixelRatio: window.devicePixelRatio || 1
  });

  // Wait until the style (and its default sprite) is fully loaded.
  await new Promise(resolve => map.once('style.load', resolve));

  // ----------------------------------------------------------------
  // 3.2 Load every SVG, then register it with map.addImage()
  // ----------------------------------------------------------------
  const loadPromises = CATEGORIES.map(async cat => {
    const url = `${ICON_BASE_URL}${cat}.svg`;
    const img = await loadSvgAsImage(url);
    // `addImage` rasterises the SVG at the element's intrinsic size.
    // You can pass extra options (pixelRatio, sdf, stretchX, …) if you
    // need them – for plain icons the defaults are fine.
    map.addImage(cat, img, { pixelRatio: 1, sdf: false });
  });

  // If any icon fails to load we want to know early.
  try {
    await Promise.all(loadPromises);
    console.log('All icons loaded and registered.');
  } catch (e) {
    console.error(e);
    // You may decide to continue with a fallback icon or abort.
    return;
  }

  // ----------------------------------------------------------------
  // 3.3 Add the GeoJSON source with ~5 000 venues
  // ----------------------------------------------------------------
  // In a real app you would fetch this from a server.  Here we generate
  // a tiny example; replace `venuesGeoJSON` with your actual data.
  const venuesGeoJSON = {
    type: 'FeatureCollection',
    features: []   // <-- fill with your 5 000 points
  };

  // Example generator (remove when you have real data)
  for (let i = 0; i < 5000; i++) {
    const lon = -122.45 + Math.random() * 0.1;
    const lat = 37.75  + Math.random() * 0.1;
    const cat = CATEGORIES[i % CATEGORIES.length];
    venuesGeoJSON.features.push({
      type: 'Feature',
      geometry: { type: 'Point', coordinates: [lon, lat] },
      properties: { category: cat, name: `${cat} #${i}` }
    });
  }

  map.addSource('venues', {
    type: 'geojson',
    data: venuesGeoJSON
  });

  // ----------------------------------------------------------------
  // 3.4 Symbol layer that uses the runtime‑registered icons
  // ----------------------------------------------------------------
  map.addLayer({
    id: 'venue-icons',
    type: 'symbol',
    source: 'venues',
    layout: {
      // The value of `icon-image` is taken from the feature property
      // `category`.  Because we registered each SVG with the same id,
      // this works out‑of‑the‑box.
      'icon-image': ['get', 'category'],

      // OPTIONAL: make the icons a little smaller on the map.
      // Adjust to suit your SVG size.
      'icon-size': 0.7,

      // Keep the default collision handling (icon‑allow‑overlap: false)
      // so that when you are zoomed out the map hides icons that would
      // otherwise overlap.
      // If you ever want to force every icon to draw, set:
      // 'icon-allow-overlap': true,
    },
    paint: {
      // If you want a subtle halo so the icons stand out on busy basemaps:
      // 'icon-halo-color': '#fff',
      // 'icon-halo-width': 1,
    }
  });

  // ----------------------------------------------------------------
  // 3.5 (Optional) add a label layer so each venue also shows its name
  // ----------------------------------------------------------------
  map.addLayer({
    id: 'venue-labels',
    type: 'symbol',
    source: 'venues',
    layout: {
      'text-field': ['get', 'name'],
      'text-font': ['Open Sans Regular', 'Arial Unicode MS Regular'],
      'text-size': 12,
      'text-offset': [0, 1.2],
      // Let the label appear even if the icon is hidden by collision.
      'text-allow-overlap': true,
      'text-ignore-placement': false
    },
    paint: {
      'text-color': '#222',
      'text-halo-color': '#fff',
      'text-halo-width': 1
    }
  });

  // --------------------------------------------------------------
  // 4️⃣  Done – the map now shows 5 000 venues with SVG icons,
  //      and MapLibre automatically hides overlapping icons.
  // --------------------------------------------------------------
})();
</script>

</body>
</html>
```

### How the code works

| Step | What happens | Why it matters |
|------|--------------|----------------|
| **Map creation** (`new maplibregl.Map`) | Loads a base style (any style you like). | The style provides the background, labels, and the *default* sprite – we don’t need to touch it. |
| **`style.load`** | Guarantees the style’s sprite is ready before we register our own images. | `addImage` can only be called after the style has been parsed. |
| **Load each SVG** (`loadSvgAsImage`) | Creates an `HTMLImageElement`, sets `crossOrigin='anonymous'`, waits for `onload`. | MapLibre rasterises the element; CORS is required when the SVG is on a different origin. |
| **`map.addImage(id, img)`** | Registers the rasterised SVG under the id that matches the category name. | Symbol layers reference images by **id**, not by URL. |
| **GeoJSON source** (`map.addSource('venues', …)`) | Supplies the 5 000 point features. | Symbol layers read geometry and properties from this source. |
| **Symbol layer** (`icon-image: ['get','category']`) | For each feature the value of its `category` property is used as the image id. | No per‑feature work is needed – the layer automatically picks the right icon. |
| **Collision handling** (default) | `icon-allow-overlap` is `false` by default, so overlapping icons are hidden. | When you zoom out the map stays readable; you can override it if you ever need every icon to draw. |
| **Optional label layer** | Shows the venue name next to the icon, with `text-allow-overlap:true` so the label appears even if the icon is culled. | Improves discoverability without cluttering the map. |

### Things to double‑check for your own deployment

1. **CORS on the SVG host** – the server must send `Access‑Control‑Allow‑Origin: *` (or your domain) so the browser can read the image data.  
2. **SVG size** – MapLibre rasterises the SVG at its intrinsic width/height. If the SVGs are huge, set `icon-size` (or edit the SVG viewBox) to keep them appropriately sized.  
3. **Performance** – 5 000 points is well within the comfort zone of a single symbol layer. If you ever go to > 50 000 points, consider clustering or using `icon-allow-overlap:true` with `icon-ignore-placement:true` to avoid the collision algorithm’s cost.  
4. **Sprite fallback** – If you ever need a fallback for a missing category, you can add a `default` image and use an expression like `['coalesce', ['image', ['get','category']], 'default']`.  

That’s it! Drop the HTML into a file, replace the `ICON_BASE_URL` and the generated `venuesGeoJSON` with your real data, and you’ll have a fast, collision‑aware map of 5 000 venues each rendered with its own SVG icon. Happy mapping!

## TL;DR  
*The current heuristic (`text‑anchor` missing **and** `symbol‑placement === "point"`) is **not reliable** for detecting route‑shield layers.*  
A shield is identified by **how the icon is sized around its text**, not by the presence or absence of `text-anchor`. The property that makes a symbol a shield is **`icon-text-fit`** (usually set to `"both"` or `"width"` together with `icon-text-fit-padding`).  

So, in a style‑audit script you should:

1. **Look for `icon-text-fit`** (or an expression that resolves to a non‑`"none"` value).  
2. Optionally verify that the layer also has an `icon-image` that resolves to a *stretchable* sprite entry (`stretchX`/`stretchY` + `content`) – this is what lets the badge grow with the road number.  
3. If you need a quick‑and‑dirty check, also test that the layer’s `icon-image` contains a placeholder like `{ref}` / `{network}` or matches a known shield‑naming pattern (`*_shield*`, `*_interstate*`, `road_*`, etc.).  

Below is a deeper explanation of why the old heuristic fails, what the spec says about shields, and a ready‑to‑paste code snippet you can drop into a Node/Browser audit script.

---

## 1. Why the old heuristic is unsound

| Heuristic condition | What it actually catches | Why it mis‑classifies |
|---------------------|--------------------------|----------------------|
| `layer.layout['text-anchor'] === undefined` | Many *plain* point‑symbol layers (e.g. POI icons, place‑name symbols) omit `text-anchor` because they rely on the default `"center"` value. | The spec says `text-anchor` defaults to `"center"`; the property is **optional** for any symbol that has a `text-field`. Its absence tells you nothing about shields. |
| `layer.layout['symbol-placement'] === 'point'` | Almost every point‑based symbol layer (places, POIs, custom markers) uses `"point"` placement. | Shields are also point‑placed, but so are *all* other point symbols. The condition is too generic. |

Result: **every point‑symbol layer that doesn’t explicitly set `text-anchor` is flagged as a shield**, which includes the majority of place‑name layers, while many shield layers that *do* set `text-anchor` (or rely on the default) slip through.

### What the spec actually says about shields

* **`icon-text-fit`** – The only layout property that tells the renderer to *scale an icon around the text* is `icon-text-fit`.  
  * Values: `"none"` (default), `"width"`, `"height"`, `"both"`.  
  * When set to `"both"` (or `"width"`/`"height"`), the engine stretches the icon according to the `icon-text-fit-padding` and the `stretchX`/`stretchY`/`content` metadata stored in the sprite JSON. This is the core of a shield: the badge grows to fit the road number.

* **`icon-image`** – Shields normally reference a *stretchable* sprite entry whose name contains a placeholder (e.g. `"us-interstate_{ref_length}"`). The placeholder is replaced at render time with the length of the road number, producing a different image name per feature.

* **`icon-text-fit-padding`** – Provides the padding around the text inside the badge; without it the badge would be clipped.

If any of those three pieces are missing, the layer cannot render a proper shield.

---

## 2. A robust heuristic for “is this a shield layer?”

Below is a **step‑by‑step decision tree** you can implement in JavaScript (or any language that can read the style JSON). It works even when layout values are **expressions**.

```js
/**
 * Returns true if a symbol layer looks like a route‑shield layer.
 *
 * @param {object} layer – a layer object from a MapLibre style.
 * @returns {boolean}
 */
function isShieldLayer(layer) {
  // 1. Must be a symbol layer.
  if (layer.type !== 'symbol') return false;

  const layout = layer.layout || {};

  // -----------------------------------------------------------------
  // 2. icon-text-fit must be present and not "none".
  //    It can be a literal string or an expression that evaluates to a string.
  // -----------------------------------------------------------------
  const iconTextFit = layout['icon-text-fit'];
  if (!iconTextFit) return false; // missing → not a shield

  // Helper to resolve simple expressions (["case", ...] etc.) is optional.
  // For a quick audit we only accept literal strings.
  const fitValue = typeof iconTextFit === 'string' ? iconTextFit : null;
  if (!fitValue || fitValue === 'none') return false;

  // -----------------------------------------------------------------
  // 3. There must be an icon-image that resolves to a *stretchable* sprite.
  //    We cannot know the sprite content at audit time, but we can look
  //    for placeholder patterns that styles use for shields.
  // -----------------------------------------------------------------
  const iconImage = layout['icon-image'];
  if (!iconImage) return false;

  // If the value is an expression, try to extract a string pattern.
  // Most shield layers use a string with placeholders like:
  //   "us-interstate_{ref_length}"
  //   "road_{ref_length}"
  //   "shield_{network}_{ref}"
  const iconStr = typeof iconImage === 'string' ? iconImage : null;
  if (!iconStr) return false; // expression → give up (conservative)

  const shieldPattern = /(?:^|:)(?:us|ca|eu|road|shield|interstate|highway|state)[_-].*{[^}]+}/i;
  if (!shieldPattern.test(iconStr)) return false;

  // -----------------------------------------------------------------
  // 4. (Optional but recommended) Verify that the sprite entry is stretchable.
  //    This requires loading the sprite JSON for the sheet that the
  //    layer resolves against. If you have the sprite JSON handy:
  // -----------------------------------------------------------------
  //   const spriteId = resolveSpriteId(layer, iconStr); // see note below
  //   const spriteMeta = spriteJson[spriteId];
  //   if (!spriteMeta || !spriteMeta.stretchX || !spriteMeta.stretchY) return false;
  //   // also check spriteMeta.content exists

  // If you cannot load the sprite, stop here – the previous checks are already
  // strong enough to avoid most false positives.

  return true;
}
```

### How the function works

| Step | Why it matters |
|------|----------------|
| **1. type === 'symbol'** | Only symbol layers can render shields. |
| **2. `icon-text-fit` present & not `"none"`** | This is the *definitive* flag that the layer wants the icon to stretch around its text. |
| **3. `icon-image` contains a placeholder** | Shields use a placeholder (`{ref}`, `{ref_length}`, `{network}`) so the image name changes per feature. The regex catches the most common naming conventions. |
| **4. (optional) sprite stretch metadata** | Guarantees the badge can actually stretch; without it the icon would be clipped. This step requires the sprite JSON, which you may already have if you audit the whole style bundle. |

If you need to support **expressions** (e.g. `["concat", "us-interstate_", ["get", "ref_length"]]`), you can add a tiny expression‑evaluator that resolves literals and `["get", …]` against a mock feature. For a quick audit, ignoring expressions is fine – you’ll simply miss a few shield layers that use complex expressions, which is safer than mis‑labeling place‑name layers.

---

## 3. How to resolve the sprite sheet for a given `icon-image`

When the style uses the **array form** for `sprite` (multiple sheets), the image name may be prefixed with `sheetId:`. The helper below shows how to extract the sheet id and the raw image name:

```js
/**
 * Returns {sheetId, imageName} for a given icon-image string.
 * Handles the default sheet (no prefix) and explicit prefixes.
 *
 * @param {string} iconImage
 * @returns {{sheetId:string, imageName:string}}
 */
function parseIconImage(iconImage) {
  const parts = iconImage.split(':');
  if (parts.length === 2) {
    return { sheetId: parts[0], imageName: parts[1] };
  }
  // No prefix → default sheet
  return { sheetId: 'default', imageName: iconImage };
}
```

You can then look up the sprite JSON for that `sheetId` (the style’s `sprite` array contains objects `{id, url}`; fetch `<url>.json`).

---

## 4. Full‑example audit script (Node)

```js
#!/usr/bin/env node
// audit-shields.js
// Usage: node audit-shields.js style.json [sprite-dir]

const fs = require('fs');
const path = require('path');
const fetch = require('node-fetch'); // npm i node-fetch@2 (for CommonJS)

async function loadSpriteJson(spriteUrl) {
  const resp = await fetch(`${spriteUrl}.json`);
  if (!resp.ok) throw new Error(`Failed to fetch ${spriteUrl}.json`);
  return resp.json();
}

/**
 * Main entry point.
 */
async function main() {
  const [stylePath, spriteBase] = process.argv.slice(2);
  if (!stylePath) {
    console.error('Usage: node audit-shields.js <style.json> [spriteBase]');
    process.exit(1);
  }

  const style = JSON.parse(fs.readFileSync(stylePath, 'utf8'));

  // Build a map of sheetId → sprite JSON (if you have a local dir, read from disk)
  const spriteMap = {};
  if (Array.isArray(style.sprite)) {
    for (const { id, url } of style.sprite) {
      spriteMap[id] = await loadSpriteJson(url);
    }
  } else if (typeof style.sprite === 'string') {
    spriteMap['default'] = await loadSpriteJson(style.sprite);
  }

  const shieldLayers = [];

  for (const layer of style.layers) {
    if (isShieldLayer(layer, spriteMap)) {
      shieldLayers.push(layer.id);
    }
  }

  console.log('Detected shield layers:', shieldLayers);
}

/**
 * Enhanced version that also checks the sprite stretch metadata.
 */
function isShieldLayer(layer, spriteMap) {
  if (layer.type !== 'symbol') return false;
  const layout = layer.layout || {};

  // 1️⃣ icon-text-fit must be a non‑none literal
  const fit = layout['icon-text-fit'];
  if (typeof fit !== 'string' || fit === 'none') return false;

  // 2️⃣ icon-image must be a string with a placeholder
  const icon = layout['icon-image'];
  if (typeof icon !== 'string') return false;
  const placeholder = /{[^}]+}/.test(icon);
  if (!placeholder) return false;

  // 3️⃣ optional: verify stretchable sprite entry
  const { sheetId, imageName } = parseIconImage(icon);
  const spriteJson = spriteMap[sheetId];
  if (spriteJson && spriteJson[imageName]) {
    const meta = spriteJson[imageName];
    const hasStretch = (meta.stretchX && meta.stretchX.length) ||
                       (meta.stretchY && meta.stretchY.length);
    const hasContent = Array.isArray(meta.content) && meta.content.length === 4;
    if (!hasStretch || !hasContent) {
      // Not a proper shield sprite – treat as false
      return false;
    }
  }

  // Passed all checks → treat as shield
  return true;
}

// Run
main().catch(err => {
  console.error('Error:', err);
  process.exit(1);
});
```

**What this script does**

* Loads the style JSON.  
* Fetches every sprite JSON referenced by the style (handles the array form).  
* For each symbol layer it runs the `isShieldLayer` function that checks:
  * `icon-text-fit` is set and not `"none"`.
  * `icon-image` is a string containing a `{…}` placeholder (the hallmark of a shield).
  * (Optional) the referenced sprite entry has `stretchX`/`stretchY` **and** `content` fields – the exact metadata required for a stretchable badge.  

The output is a list of layer IDs that *look* like route‑shield layers, which you can then verify manually or feed into further processing.

---

## 5. Edge Cases & Gotchas

| Situation | How the heuristic behaves | What to do |
|-----------|---------------------------|------------|
| **`icon-text-fit` is an expression** (e.g. `["case", ["==", ["get","network"], "us-interstate"], "both", "none"]`) | The simple literal‑check will reject it. | Either evaluate the expression against a representative feature set, or conservatively treat the layer as *maybe* a shield and flag it for manual review. |
| **Shield layer uses a custom image name without placeholders** (e.g. pre‑baked PNGs for each highway) | The placeholder regex will miss it. | If you know your style uses pre‑baked images, add a secondary check: look for `icon-image` that matches a known list (`us-interstate_1`, `us-interstate_2`, …) or simply check that the sprite entry has `stretchX`/`stretchY` even if there’s no placeholder. |
| **Sprite sheet is hosted locally and you cannot fetch it** | The optional stretch‑metadata

Below is a **complete, copy‑and‑paste ready** example that shows how to

1. **Create a draggable pin (MapLibre `Marker`).**  
2. **Place it at a known longitude/latitude.**  
3. **Open a `Popup` when the user clicks the pin.**  
4. (Optional) keep the popup open while the pin is being dragged and update the popup text with the new coordinates.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>MapLibre – draggable pin + popup</title>
  <meta name="viewport" content="width=device-width, initial-scale=1.0">

  <!-- MapLibre GL JS CSS -->
  <link href="https://unpkg.com/maplibre-gl@4.2.0/dist/maplibre-gl.css" rel="stylesheet" />
  <style>
    body { margin:0; padding:0; }
    #map { position:absolute; top:0; bottom:0; width:100%; }

    /* Optional: a custom pin image (you can skip this and use the default marker) */
    .my-pin {
      background-image: url('https://raw.githubusercontent.com/maplibre/maplibre-gl-js/main/docs/assets/pin.png');
      background-size: contain;
      width: 30px;
      height: 40px;
      cursor: grab;               /* visual cue that it can be moved */
    }
    .my-pin:active { cursor: grabbing; }
  </style>
</head>
<body>

<div id="map"></div>

<!-- MapLibre GL JS -->
<script src="https://unpkg.com/maplibre-gl@4.2.0/dist/maplibre-gl.js"></script>

<script>
  // -------------------------------------------------
  // 1️⃣ Initialise the map
  // -------------------------------------------------
  const map = new maplibregl.Map({
    container: 'map',                     // id of the div above
    style: 'https://demotiles.maplibre.org/style.json', // any style you like
    center: [-122.447303, 37.753574],     // initial view (lon, lat)
    zoom: 12
  });

  // Wait until the style is fully loaded before adding the marker
  map.on('load', () => {
    // -------------------------------------------------
    // 2️⃣ Create the draggable marker
    // -------------------------------------------------
    const marker = new maplibregl.Marker({
      // If you want a custom pin, give it a DOM element:
      // element: document.createElement('div')
      // element.className = 'my-pin';
      // otherwise omit `element` and the default blue pin is used.
      draggable: true
    })
      .setLngLat([-122.447303, 37.753574]) // start position
      .addTo(map);

    // -------------------------------------------------
    // 3️⃣ Create a popup (but don’t attach it yet)
    // -------------------------------------------------
    const popup = new maplibregl.Popup({
      closeButton: true,
      closeOnClick: false,   // keep it open when you click elsewhere
      offset: 25              // distance from the pin tip
    })
      .setHTML('<strong>Drag me!</strong><br/>Coordinates: <span id="coords"></span>');

    // Helper to update the coordinate text inside the popup
    function updatePopupContent(lngLat) {
      const el = document.getElementById('coords');
      if (el) {
        el.textContent = `${lngLat.lng.toFixed(5)}, ${lngLat.lat.toFixed(5)}`;
      }
    }

    // -------------------------------------------------
    // 4️⃣ Show the popup when the pin is clicked
    // -------------------------------------------------
    // The marker’s DOM element is accessible via marker.getElement()
    marker.getElement().addEventListener('click', (e) => {
      // Prevent the map’s click handler from also firing
      e.stopPropagation();

      // Position the popup at the marker’s current location
      popup.setLngLat(marker.getLngLat()).addTo(map);
      updatePopupContent(marker.getLngLat());
    });

    // -------------------------------------------------
    // 5️⃣ Keep the popup in sync while dragging (optional)
    // -------------------------------------------------
    marker.on('dragend', () => {
      const lngLat = marker.getLngLat();

      // If the popup is already open, move it to the new location
      if (popup.isOpen()) {
        popup.setLngLat(lngLat);
        updatePopupContent(lngLat);
      }
    });

    // -------------------------------------------------
    // 6️⃣ Close the popup when the map is clicked elsewhere (optional)
    // -------------------------------------------------
    map.on('click', () => {
      if (popup.isOpen()) popup.remove();
    });
  });
</script>

</body>
</html>
```

---

## How It Works – Step‑by‑Step Explanation

| Step | What happens | Why it matters |
|------|--------------|----------------|
| **1️⃣ Initialise the map** | `new maplibregl.Map({ … })` creates the canvas, loads the style, and centers on a coordinate. | You need a map instance before you can add any UI element. |
| **2️⃣ Create the draggable marker** | `new maplibregl.Marker({draggable:true})` builds a DOM element (default blue pin or a custom one you supply) and registers the drag‑handling code inside MapLibre. | `Marker` lives **outside** the style, so it’s drawn on top of every layer and can be moved without rebuilding a sprite. |
| **3️⃣ Create a popup** | `new maplibregl.Popup()` builds a floating HTML box that can be attached to any lng/lat. | Popups are the standard way to show extra info on click. |
| **4️⃣ Show the popup on click** | `marker.getElement().addEventListener('click', …)` attaches a native click listener to the pin’s DOM element. Inside the handler we call `popup.setLngLat(...).addTo(map)`. | `Marker` is a DOM element, not a style layer, so we listen for DOM events rather than a MapLibre `click` event on a layer. |
| **5️⃣ Keep the popup in sync while dragging** | `marker.on('dragend', …)` fires after the user releases the pin. We move the popup to the new location and optionally update its text. | Without this the popup would stay stuck at the old coordinates. |
| **6️⃣ Close the popup on map click** | `map.on('click', …)` removes the popup if the user clicks anywhere else. | Gives a clean UX; you can omit this if you want the popup to stay open. |

### Custom Pin (Optional)

If you prefer a custom image instead of the default blue pin:

```js
const el = document.createElement('div');
el.className = 'my-pin';   // CSS defined in <style> above
const marker = new maplibregl.Marker({ element: el, draggable: true })
               .setLngLat([lon, lat])
               .addTo(map);
```

You can also use an `<img>` element or any HTML you like (e.g., an SVG inline). The only requirement is that the element has a size (width/height) so MapLibre can compute the anchor point.

### Important Gotchas

| Issue | Symptom | Fix |
|-------|---------|-----|
| **Marker click also triggers map click** | Popup opens then immediately closes. | Call `e.stopPropagation()` inside the marker click handler (as shown). |
| **Popup appears offset incorrectly** | The tip of the pin is not aligned with the popup. | Use the `offset` option when creating the popup (e.g., `offset: 25`). |
| **Marker disappears after a style change** | You reload a style (`map.setStyle(...)`) and the marker is gone. | Re‑add the marker after the new style loads (`map.on('styledata', …)`), or keep the marker in a separate container (`map.addControl`) if you need it to survive style swaps. |
| **SVG icons look blurry on high‑DPI screens** | The custom pin is rasterized at 1× size. | Provide a higher‑resolution image (e.g., 2×) and set `style.width/height` accordingly, or use a vector‑based HTML/SVG element directly. |

---

## TL;DR – Minimal Code Snippet

If you just need the absolute minimum (default pin, no custom styling):

```js
map.on('load', () => {
  const marker = new maplibregl.Marker({ draggable: true })
    .setLngLat([lon, lat])
    .addTo(map);

  const popup = new maplibregl.Popup({ offset: 25 })
    .setHTML('Hello!');

  marker.getElement().addEventListener('click', e => {
    e.stopPropagation();
    popup.setLngLat(marker.getLngLat()).addTo(map);
  });

  marker.on('dragend', () => {
    if (popup.isOpen()) popup.setLngLat(marker.getLngLat());
  });
});
```

Replace `lon` and `lat` with the coordinate you want the pin to start at.

